  "ui.footer.tagline":
    "हाइब्रिड इंफ्रास्ट्रक्चर कंट्रोल प्लेन। भरोसे के साथ अपने Homelab को deploy, प्रबंधित और मॉनिटर कीजिए।",
  "ui.configFlow.defaultCredentials": "डिफ़ॉल्ट लॉगिन क्रेडेंशियल:",
