  "ui.managed.nodeConfiguration": "Node कॉन्फ़िगरेशन",
  "ui.managed.selectProvider":
    "प्रबंधित Node जोड़ने से पहले नीचे Centron या IONOS चुनिए। इस StackKit डिप्लॉयमेंट में अभी कोई प्रदाता चुना हुआ नहीं है।",
