  "wizard.smartHome.applianceRetained":
    "अलग Home Assistant OS अनुरोध सहेज लिया गया है। इस रोलआउट को फिर शुरू करने पर वही अप्लायंस रहता है। उसका नेटिव API कनेक्शन और तैयारी अलग से सत्यापित होती है।",
