  "wizard.smartHome.verified-proxmox-lan-and-guest-capacity":
    "जुड़ा हुआ Proxmox होस्ट, अलग VM के लिए पर्याप्त क्षमता और होम नेटवर्क तक पहुँच सत्यापित कीजिए।",
  "wizard.smartHome.verify-local-device-reachability":
    "आपके घर के डिवाइस तक पहुँच का सत्यापन अभी बाकी है। सिर्फ़ उपलब्ध नेटवर्क ब्रिज इसका प्रमाण नहीं है।",
