  "ui.taskStatus.theLeaseCapturesRuntimeState":
    "लीज़ रनटाइम स्थिति, बिलिंग अवधि और उस प्रबंधित प्रदाता को दर्ज करती है जो Cloud Kit होस्ट करेगा।",
  "ui.taskStatus.thePersistedSpecLinksBack":
    "सहेजा गया स्पेक आवश्यकताओं की फ़ाइल और मूल StackKit डिप्लॉयमेंट अनुरोध से वापस जुड़ा होता है।",
  "ui.taskStatus.theSimulationGateProtectsThe":
    "सिमुलेशन गेट पहले रोलआउट और बाद के अपडेट फ़्लो को असुरक्षित बदलावों से बचाता है।",
  "ui.taskStatus.theSpecContainsAllConfiguration":
    "स्पेक में आपके Homelab को डिप्लॉय करने के लिए ज़रूरी सारा कॉन्फ़िगरेशन है। इसे वर्ज़न कंट्रोल में रखा जा सकता है और किसी भी संगत Node पर दोहराया जा सकता है।",
  "ui.taskStatus.theUnifiedSpecIsThe":
    "एकीकृत स्पेक StackKits और रनटाइम सत्यापन का मानक इनपुट है।",
  "ui.taskStatus.thisChecksFeatureSelectionsAccess":
    "यह सुविधा चयन, एक्सेस मोड, उपयोगकर्ता कॉन्फ़िगरेशन और ऑथेंटिकेशन सेटिंग्स की संगति जाँचता है।",
  "ui.taskStatus.thisChecksThatThePersisted":
    "यह जाँचता है कि सहेजा गया StackKit डिप्लॉयमेंट स्पेक और requirements-spec.yaml अब भी मेल खाते हैं, फिर StackKits आर्टिफ़ैक्ट जनरेशन शुरू होने से पहले पुष्टि करता है कि प्रबंधित VM लीज़ रनटाइम SSH होस्ट या सार्वजनिक IP उपलब्ध कराती है।",
  "ui.taskStatus.thisIsThePointWhere":
    "यही वह बिंदु है जहाँ चुनी गई सेवाएँ रनटाइम लक्ष्य पर इंस्टॉल और कॉन्फ़िगर होती हैं।",
  "ui.taskStatus.thisNonInteractivePrepStep":
    "यह गैर-इंटरैक्टिव प्रिप चरण Cloud Kit लागू करने से पहले वे टूल इंस्टॉल और जाँचता है जिनकी StackKits को ज़रूरत है।",
  "ui.taskStatus.thisStackKitDeploymentConfigurationIs":
    "यह StackKit डिप्लॉयमेंट कॉन्फ़िगरेशन सुरक्षित रूप से सहेजा जाता है और बाद में डैशबोर्ड से एक्सपोर्ट या संशोधित किया जा सकता है।",
  "ui.taskStatus.validatingChoicesAndBuildingThe":
    "चुनावों का सत्यापन और डिप्लॉयमेंट स्पेक बनाया जा रहा है",
  "ui.taskStatus.validatingConfiguration": "कॉन्फ़िगरेशन सत्यापित हो रहा है",
  "ui.taskStatus.validatingTheBackupAndRestore":
    "StackKit डिप्लॉयमेंट को सत्यापित चिह्नित करने से पहले बैकअप और रिस्टोर मार्ग सत्यापित हो रहा है।",
  "ui.taskStatus.validatingTheUpdatePathBefore":
    "प्रबंधित रनटाइम पर रोलआउट लागू करने से पहले अपडेट मार्ग सत्यापित हो रहा है।",
  "ui.taskStatus.verificationConfirmsThatTheStackKit":
    "सत्यापन पुष्टि करता है कि StackKit डिप्लॉयमेंट उपयोग योग्य है, सिर्फ़ यह नहीं कि फ़ाइलें जनरेट हो गईं।",
